// Original educational adaptations. Age ranges organise invitations, not developmental tests.
export const pathwaySources=Object.freeze({
 responsive:{title:'HSE · comunicación de 0 a 12 meses',url:'https://www2.hse.ie/babies-children/checks-milestones/communication-development/0-12-months/',date:'2026-11-01',type:'Guía pública; no ensayo de esta aplicación'},
 play:{title:'AAP · The Power of Play',url:'https://publications.aap.org/pediatrics/article/142/3/e20182058/37364/The-Power-of-Play-A-Pediatric-Role-in-Enhancing',date:'2026-11-01',type:'Informe clínico sobre juego; adaptación no evaluada'},
 executive:{title:'Harvard · actividades de funciones ejecutivas',url:'https://developingchild.harvard.edu/resources/handouts-tools/activities-guide-enhancing-and-practicing-executive-function-skills/',date:'2026-11-01',type:'Guía de actividades; no validación de esta aplicación'},
 identity:{title:'UCLA · valores, metas e identidad',url:'https://developingadolescent.semel.ucla.edu/core-science-of-adolescence/developing-values-goals-and-identity',date:'2026-11-01',type:'Síntesis universitaria; no predicción individual'}
});
const common={reviewStatus:'Adaptación escrita; revisión pedagógica y pruebas con familias pendientes',evidenceType:'Diseño educativo informado por fuentes; no intervención terapéutica evaluada',stopCues:'Puedes parar ante cansancio, incomodidad o falta de interés. No hace falta completar los pasos.',adaptations:'Se puede escuchar, señalar, gesticular o permanecer en silencio; no se exige una respuesta verbal.',safety:'La persona adulta selecciona materiales apropiados y supervisa. Sin piezas pequeñas, cuerdas, pilas ni imanes accesibles.'};
const path=(id,ageRange,title,domains,caregiverRole,materials,steps,childCues,source,route=null)=>Object.freeze({...common,id,ageRange,title,domains,caregiverRole,materials,steps,childCues,sourceURL:pathwaySources[source].url,sourceDate:pathwaySources[source].date,sourceTitle:pathwaySources[source].title,sourceType:pathwaySources[source].type,route,status:'Guía disponible · fuera de pantalla'});
export const learningPathways=Object.freeze([
 path('4-6','4–6 meses','Un sonido y un turno',['Lenguaje','Vínculo','Bienestar'],'Adulto presente, atento y conductor. La pantalla es para ti.','Tu voz; no hace falta ningún objeto.',['Cuando esté despierto y cómodo, ofrece un sonido suave o una frase en una lengua familiar.','Haz una pausa. Puedes acompañar un sonido espontáneo, un gesto o el silencio.','Sigue su interés o termina. No pidas imitación ni contacto visual.'],'Observa el momento sin medir atención, inteligencia o hitos.','responsive'),
 path('6-9','6–9 meses','Narrar lo que sucede',['Lenguaje','Juego','Exploración'],'Adulto presente: sostiene, nombra y espera.','Un objeto grande y adecuado que sostengas tú.',['Sigue algo que ya le interese y nómbralo con una frase sencilla.','Describe una acción tuya y deja una pausa. No fuerces postura ni movimiento.','Repite solo si el momento resulta agradable; puedes volver al silencio.'],'Mirar algo ahora no define una preferencia estable.','responsive'),
 path('9-12','9–12 meses','Aparecer y volver',['Juego','Vínculo','Exploración'],'Adulto conductor; no es una tarea para superar.','Tus propias manos; ningún objeto sobre la cara del bebé.',['Si resulta agradable, oculta brevemente TU rostro detrás de TUS manos.','Descúbrete con suavidad y deja un turno. Nunca cubras la cara del bebé.','Cambia de juego o termina según su interés. No se exige sonrisa ni búsqueda.'],'Cualquier respuesta o ninguna están bien.','executive'),
 path('12-17','12–17 meses','Dentro y fuera, juntos',['Juego','Autonomía progresiva','Lenguaje'],'Adulto al lado, preparando y supervisando.','Un recipiente estable y dos objetos grandes, adecuados e íntegros.',['Mete un objeto grande en el recipiente una vez y describe tu acción.','Invita a sacar, meter, mirar o elegir entre dos objetos; también puede pasar.','Guardad juntos si quiere. Aparta la pantalla para este juego.'],'La elección de hoy no se guarda como rasgo de personalidad.','play'),
 path('18-35','18–35 meses','Una historia compartida',['Juego','Emociones','Vínculo'],'Adulto presente; acompaña y ayuda a regular emociones.','Un muñeco adecuado o un objeto cotidiano grande y seguro.',['Saluda al muñeco y ofrece una acción sencilla: descansar, saludar o guardar.','Sigue una idea del pequeño o describe lo que ocurre, sin exigir imitación.','Si algo molesta, ofrece consuelo y termina. No evalúes su conducta.'],'Observa la iniciativa y acompaña; no diagnostiques emociones.','play','2y:original'),
 path('3-5','3–5 años','Construir una historia',['Creatividad','Lenguaje','Juego'],'Adulto disponible para leer o ayudar; sin lectoescritura obligatoria.','Papel y materiales grandes adecuados, o solo imaginación.',['Propón un lugar o una figura y deja elegir.','Inventad juntos qué podría pasar; se puede dibujar, señalar o contar.','Cambiad una parte de la historia o dejadla abierta.'],'La explicación puede ser un gesto; no hay historia perfecta.','play'),
 path('6-8','6–8 años','Planear, probar, cambiar',['Razonamiento','Autonomía progresiva','Matemáticas'],'Ayuda gradual: una pista y un turno para pensar.','Papel para dibujar una idea; en la app hay fichas digitales.',['Piensa cómo repartir una colección en dos partes.','Prueba una forma y conserva el registro antes de cambiarla.','Explica o dibuja qué cambió y qué permaneció.'],'Un error ofrece algo que revisar, sin etiquetas sobre capacidades.','executive','5y:number-parts'),
 path('9-12','9–12 años','Dos planes y un criterio',['Autonomía progresiva','Convivencia','Razonamiento'],'Apoyo disponible; explicar oralmente o en papel es opcional.','Un presupuesto ficticio en la actividad existente.',['Mira las condiciones de una salida y prepara un plan.','Conserva A y construye B con las mismas condiciones.','Compara lo que cambió y explica un criterio si quieres. Más barato no significa mejor.'],'No se puntúan responsabilidad, familia ni personalidad.','executive','7y:original'),
 path('13-15','13–15 años','Una afirmación, varias razones',['Pensamiento crítico','Culturas diversas','Autonomía progresiva'],'Ayuda opcional; deja espacio para discrepar con razones.','Un caso ficticio del taller existente 13–18.',['Distingue qué dice el registro y qué añade una conclusión.','Busca una razón alternativa y comprueba qué dato necesitarías.','Revisa tu idea o mantenla con una explicación. No tienes que compartir intereses personales.'],'Metas y preferencias pueden cambiar; no se crea un perfil.','identity','12y:arguments'),
 path('16-17','16–17 años','Decisiones que se pueden revisar',['Pensamiento crítico','Autonomía progresiva','Bienestar'],'Acompañamiento elegido, sin vigilancia emocional.','Papel; un caso ficticio del taller 13–18 si quieres practicar.',['Imagina dos opciones de estudio, oficio o proyecto sin introducir datos personales.','Anota qué información falta y una forma de comprobarla.','Revisa un criterio con otra perspectiva. No hace falta elegir una carrera hoy.'],'Es exploración, no un test vocacional ni una promesa de carrera ideal.','identity','12y:arguments'),
 path('18+','18 años en adelante','Continuar con criterio propio',['Pensamiento crítico','Aprendizaje continuo','Culturas diversas'],'La persona adulta decide qué compartir; no hay acceso parental automático.','Papel o el taller de argumentos existente, rotulado 13–18.',['Elige una afirmación pública o un caso ficticio. No introduzcas datos privados.','Separa evidencia, inferencia e información que falta.','Propón otra explicación y una comprobación posible. Puedes parar sin una conclusión.'],'Práctica abierta; todavía no hay itinerario adulto completo.','identity','12y:arguments')
]);
export function pathwayMarkup(){return `<details class="pathway-guide"><summary>Guía por etapas · del primer año a 18+</summary><p>Invitaciones flexibles para conversar, jugar y explorar. Las franjas se solapan: no son niveles ni una lista de hitos que cumplir.</p><label for="pathway-stage">Explorar una etapa</label><select id="pathway-stage">${learningPathways.map(p=>`<option value="${p.id}">${p.ageRange}</option>`).join('')}</select><div id="pathway-card"></div><p class="quiet">Las lenguas familiares se mantienen. Un idioma no representa una sola cultura. Los gustos cambian: aquí no inferimos inteligencia, personalidad ni vocación.</p></details>`;}
export function bindPathways(root,{launch}){
 const select=root.querySelector('#pathway-stage'),card=root.querySelector('#pathway-card');if(!select||!card)return;
 function draw(){const p=learningPathways.find(x=>x.id===select.value)||learningPathways[0];card.innerHTML=`<article><p class="eyebrow">${p.status}</p><h2>${p.title}</h2><p>${p.domains.join(' · ')}</p><p><strong>Acompañamiento:</strong> ${p.caregiverRole}</p><p><strong>Materiales:</strong> ${p.materials}</p><ol>${p.steps.map(s=>`<li>${s}</li>`).join('')}</ol><p>${p.childCues}</p><p>${p.stopCues}</p><p>${p.adaptations}</p>${['4-6','6-9','9-12'].includes(p.id)?`<button type="button" class="action secondary" data-early-language data-early-stage="${p.id}">Ver la guía auditiva del adulto</button>`:p.route?`<button type="button" class="action secondary" data-pathway-route="${p.route}">${['13-15','16-17','18+'].includes(p.id)?'Abrir taller existente · 13–18 años':p.id==='18-35'?'Ver guía existente · 24–35 meses':'Abrir propuesta relacionada'}</button>`:''}<details><summary>Seguridad, fuentes y alcance</summary><p>${p.safety}</p><p>${p.reviewStatus}. ${p.evidenceType}.</p><p><a href="${p.sourceURL}" target="_blank" rel="noopener noreferrer">${p.sourceTitle}</a> · fuente consultada ${p.sourceDate}. ${p.sourceType}.</p><p>Esta pantalla no registra elecciones ni respuestas. Los juegos existentes pueden guardar su avance local en este navegador compartido; eso no proporciona una cuenta privada.</p></details></article>`;card.querySelector('[data-pathway-route]')?.addEventListener('click',e=>launch(e.currentTarget.dataset.pathwayRoute));}
 select.onchange=draw;draw();
}
